#!/usr/bin/env python3
"""Write the Android host's MainActivity (SAF + media channels).

The DreamTX repo does not commit the android platform folder — it is
regenerated by `flutter create` on every CI run (which only creates
MISSING files, so a checked-in host would silently drift from what the
build actually compiles). This script runs right after `flutter create`
and REPLACES the generated template MainActivity with DreamTX's own:

  * it registers the `dreamtx/saf` method channel;
  * `list` walks one picked SAF tree URI (files in subfolders included,
    breadth-first, hard-capped) via pure DocumentsContract queries — no
    extra AndroidX dependencies needed on the classpath;
  * `copyToCache` streams one document into the app cache and returns
    the local path, which the resource store then copies into its own
    documents tree;
  * it registers the `dreamtx/media` method channel;
  * `open` hands one resolved local media file to the system's own
    player via `ACTION_VIEW` + a FileProvider URI (the provider is
    injected below) — playback with zero bundled SDKs and zero APK
    impact. The app stays a slide tool; the device player plays.

Dart side: app/lib/core/saf_bridge.dart and app/lib/core/media_playback.dart.
Idempotent: rewriting an already-current host is a no-op; a changed host is
rewritten wholesale.
"""
import os
import sys

MAIN_ACTIVITY = r"""package com.dreamtx.dreamtx

import android.content.Intent
import android.net.Uri
import android.provider.DocumentsContract
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File

class MainActivity : FlutterActivity() {

    companion object {
        const val SAF_CHANNEL = "dreamtx/saf"
        const val MEDIA_CHANNEL = "dreamtx/media"
        const val MAX_FILES = 400
    }

    override fun configureFlutterEngine(engine: FlutterEngine) {
        super.configureFlutterEngine(engine)
        val messenger = engine.dartExecutor.binaryMessenger

        MethodChannel(messenger, SAF_CHANNEL).setMethodCallHandler { call, result ->
            try {
                when (call.method) {
                    "list" -> result.success(listTree(call.arguments as String))
                    "copyToCache" -> result.success(copyToCache(call.arguments as String))
                    else -> result.notImplemented()
                }
            } catch (e: Exception) {
                result.error("saf", e.message ?: e.javaClass.simpleName, null)
            }
        }

        MethodChannel(messenger, MEDIA_CHANNEL).setMethodCallHandler { call, result ->
            try {
                when (call.method) {
                    "open" -> {
                        val args = call.arguments as? Map<*, *>
                        val path = args?.get("path") as? String
                        val mime = (args?.get("mime") as? String) ?: "*/*"
                        if (path == null) {
                            result.error("media", "path required", null)
                        } else {
                            result.success(openMedia(path, mime))
                        }
                    }
                    else -> result.notImplemented()
                }
            } catch (e: Exception) {
                result.error("media", e.message ?: e.javaClass.simpleName, null)
            }
        }
    }

    /**
     * Lists the files inside one picked SAF tree, subfolders included
     * (breadth-first, hard-capped so a runaway tree can never wedge the
     * import). Pure DocumentsContract queries — no extra dependencies.
     */
    private fun listTree(treeString: String): Map<String, Any> {
        val tree = Uri.parse(treeString)
        val rootId = DocumentsContract.getTreeDocumentId(tree)
        val files = mutableListOf<Map<String, Any>>()
        val dirs = ArrayDeque<String>()
        dirs.addLast(rootId)
        while (dirs.isNotEmpty() && files.size < MAX_FILES) {
            val dirId = dirs.removeFirst()
            val childrenUri =
                DocumentsContract.buildChildDocumentsUriUsingTree(tree, dirId)
            contentResolver.query(
                childrenUri,
                arrayOf(
                    DocumentsContract.Document.COLUMN_DOCUMENT_ID,
                    DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                    DocumentsContract.Document.COLUMN_MIME_TYPE,
                    DocumentsContract.Document.COLUMN_SIZE,
                ),
                null, null, null
            )?.use { cursor ->
                while (cursor.moveToNext() && files.size < MAX_FILES) {
                    val id = cursor.getString(0) ?: continue
                    val name = cursor.getString(1) ?: id
                    val mime = cursor.getString(2) ?: ""
                    val docUri = DocumentsContract.buildDocumentUriUsingTree(tree, id)
                    if (mime == DocumentsContract.Document.MIME_TYPE_DIR) {
                        dirs.addLast(id)
                    } else {
                        files.add(
                            mapOf(
                                "name" to name,
                                "uri" to docUri.toString(),
                                "size" to cursor.getLong(3),
                            )
                        )
                    }
                }
            }
        }
        return mapOf(
            "rootName" to queryDisplayName(tree, rootId),
            "files" to files,
        )
    }

    /** The picked tree's own display name — what the folder is called. */
    private fun queryDisplayName(tree: Uri, docId: String): String {
        val docUri = DocumentsContract.buildDocumentUriUsingTree(tree, docId)
        return try {
            contentResolver.query(
                docUri,
                arrayOf(DocumentsContract.Document.COLUMN_DISPLAY_NAME),
                null, null, null
            )?.use { cursor ->
                if (cursor.moveToFirst()) cursor.getString(0) ?: docId else docId
            } ?: docId
        } catch (_: Exception) {
            docId
        }
    }

    /**
     * Streams one document into the app cache and returns the local path
     * — the resource store then copies it into its own documents tree.
     */
    private fun copyToCache(uriString: String): String {
        val uri = Uri.parse(uriString)
        val target = File(
            cacheDir,
            "saf-" + System.currentTimeMillis() + "-" + uriString.hashCode()
        )
        contentResolver.openInputStream(uri)?.use { input ->
            target.outputStream().use { output -> input.copyTo(output) }
        } ?: throw IllegalStateException("unreadable document: $uriString")
        return target.absolutePath
    }

    /**
     * Opens one resolved local media file with the system's own player —
     * ACTION_VIEW over a FileProvider URI (the provider + its paths are
     * injected by this script). Returns false when the file is gone or no
     * activity can handle the type; the Dart side surfaces that quietly.
     *
     * Files can live OUTSIDE the provider's declared roots: the resource
     * store writes under getApplicationDocumentsDirectory(), which on
     * Android is `<data>/app_flutter/` — a SIBLING of `files/`, not inside
     * it — so `files-path` does not cover it and getUriForFile throws
     * IllegalArgumentException. Such files are staged into the cache
     * (a covered root) as `media-preview-<name>` and the CACHED uri is
     * shared; any previous staging file is deleted first so one preview
     * at a time ever occupies the cache.
     */
    private fun openMedia(path: String, mime: String): Boolean {
        val file = File(path)
        if (!file.exists() || !file.canRead()) return false
        return try {
            val uri = try {
                FileProvider.getUriForFile(
                    this, "$packageName.fileprovider", file
                )
            } catch (_: IllegalArgumentException) {
                // Outside every declared root (app_flutter and friends):
                // stage a cache copy and share THAT uri.
                stagedMediaUri(file) ?: return false
            }
            val intent = Intent(Intent.ACTION_VIEW).apply {
                setDataAndType(uri, mime)
                addFlags(
                    Intent.FLAG_GRANT_READ_URI_PERMISSION
                        or Intent.FLAG_ACTIVITY_NEW_TASK
                )
            }
            if (intent.resolveActivity(packageManager) == null) {
                // No dedicated player: fall back to a generic view intent —
                // the chooser decides; false only when truly nothing exists.
                val generic = Intent(Intent.ACTION_VIEW).apply {
                    data = uri
                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                }
                if (generic.resolveActivity(packageManager) == null) return false
                startActivity(generic)
            } else {
                startActivity(intent)
            }
            true
        } catch (_: Exception) {
            false
        }
    }

    /**
     * Copies a file outside the provider's roots into cacheDir and returns
     * the provider uri for the staged copy (null when the copy fails).
     * Deletes any previous `media-preview-*` file first — the cache never
     * accumulates stale previews.
     */
    private fun stagedMediaUri(source: File): Uri? {
        return try {
            cacheDir.listFiles()?.forEach { f ->
                if (f.name.startsWith("media-preview-")) f.delete()
            }
            val safe = source.name.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val target = File(cacheDir, "media-preview-" + safe)
            source.inputStream().use { input ->
                target.outputStream().use { output -> input.copyTo(output) }
            }
            FileProvider.getUriForFile(
                this, "$packageName.fileprovider", target
            )
        } catch (_: Exception) {
            null
        }
    }
}
"""

# The FileProvider the media channel shares local files through — without
# it, file:// URIs cannot cross app boundaries (API 24+).
MANIFEST_PROVIDER = """        <!-- The media playback channel shares resolved local files with the
             system player through this provider (file:// URIs are banned
             cross-app since API 24). -->
        <provider
            android:name="androidx.core.content.FileProvider"
            android:authorities="${applicationId}.fileprovider"
            android:exported="false"
            android:grantUriPermissions="true">
            <meta-data
                android:name="android.support.FILE_PROVIDER_PATHS"
                android:resource="@xml/file_paths" />
        </provider>
"""

FILE_PATHS_XML = """<?xml version="1.0" encoding="utf-8"?>
<!-- The resource store's roots the media channel may share with the system
     player: the app's own documents tree (where deck resources live) and
     its cache (the SAF import staging area AND the media preview copies —
     files under app_flutter/, which files-path does NOT cover, are staged
     there by MainActivity.stagedMediaUri). -->
<paths xmlns:android="http://schemas.android.com/apk/res/android">
    <files-path name="documents" path="." />
    <cache-path name="cache" path="." />
</paths>
"""


def _inject_provider(manifest_path: str) -> None:
    """Add the FileProvider to the CI-generated AndroidManifest (idempotent)."""
    src = open(manifest_path).read()
    if "fileprovider" in src:
        print("write_android_host: manifest already carries the provider")
        return
    anchor = "</application>"
    if anchor not in src:
        print("write_android_host: no </application> anchor in manifest — "
              "the provider was NOT injected", file=sys.stderr)
        return
    src = src.replace(anchor, MANIFEST_PROVIDER + "    " + anchor.rstrip() + "\n")
    # Re-normalize: keep the closing tag intact.
    open(manifest_path, "w").write(src)
    print("write_android_host: injected the FileProvider into the manifest")


def main() -> int:
    root = os.path.join("app", "android", "app", "src", "main")
    path = os.path.join(root, "kotlin", "com", "dreamtx", "dreamtx",
                        "MainActivity.kt")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.exists(path) and open(path).read() == MAIN_ACTIVITY:
        print("write_android_host: MainActivity.kt already current")
    else:
        open(path, "w").write(MAIN_ACTIVITY)
        print("write_android_host: wrote " + path +
              " (channels: dreamtx/saf, dreamtx/media)")

    manifest = os.path.join(root, "AndroidManifest.xml")
    if os.path.exists(manifest):
        _inject_provider(manifest)
    else:
        print("write_android_host: AndroidManifest.xml not found — "
              "provider skipped", file=sys.stderr)

    xml_dir = os.path.join(root, "res", "xml")
    os.makedirs(xml_dir, exist_ok=True)
    xml_path = os.path.join(xml_dir, "file_paths.xml")
    if os.path.exists(xml_path) and open(xml_path).read() == FILE_PATHS_XML:
        print("write_android_host: file_paths.xml already current")
    else:
        open(xml_path, "w").write(FILE_PATHS_XML)
        print("write_android_host: wrote " + xml_path)
    return 0


if __name__ == "__main__":
    sys.exit(main())
